import { createFileRoute } from "@tanstack/react-router";

import { CtaBand } from "@/components/ui/cta-band";
import { Hero } from "@/components/ui/hero";
import { SafeImage } from "@/components/ui/safe-image";
import { SiteChrome } from "@/components/ui/site-chrome";
import { StoryLead } from "@/components/ui/story-lead";

export const Route = createFileRoute("/")({ component: Home });

const CHROME = { secondAction: { label: "Call us", href: "tel:0117 496 0000" }, social: [{ network: "instagram", href: "https://instagram.com/harbourloaf" }],
  name: "Harbour Loaf",
  tagline: "A neighbourhood sourdough bakery in Bristol.",
  links: [{ label: "Today's bake", href: "/" }, { label: "The starter", href: "/starter" }, { label: "Visit", href: "/visit" }, { label: "Gallery", href: "/gallery" }, { label: "Classes", href: "/classes" }, { label: "Order", href: "/order" }],
  action: { label: "Order a loaf", href: "/order" },
  contact: {
    address: "Bristol",
    hours: "Wed–Sat 8–2, Sun 9–1",
  },
};

function Home() {
  return (
    <SiteChrome {...CHROME}>
      <Hero
        title="Harbour Loaf"
        subtitle="Overnight sourdough on a Bristol side street. See today's bake, then order a loaf and collect it from the counter."
        primary={{ label: "Order a loaf", href: "/order" }}
        secondary={{ label: "How to find us", href: "/visit" }}
      />

      <section className="mx-auto max-w-5xl px-6">
        <SafeImage
          src="/u/fold-lane-bakery/64eee06cebae214308ea0142e5163286.jpg"
          alt="Harbour Loaf on a Bristol side street in the early morning"
          ratio="16/9"
          fallbackSeed="harbour-front"
        />
      </section>

      <section className="mx-auto max-w-3xl px-6 py-20 motion-reveal">
        <StoryLead
          kicker="The starter"
          headline="Fed every morning since we opened"
          standfirst="A Bristol crock, stoneground flour, and a long cool prove. That is why a loaf here takes the time it takes."
          href="/starter"
        />
        <SafeImage focus="top"
          className="mt-8"
          src="/u/fold-lane-bakery/8e6bd4818b036cfcd639d1bb5ec6156c.jpg"
          alt="A sourdough boule cooling after the morning bake"
          ratio="4/3"
          fallbackSeed="cooling-boule"
        />
      </section>

      <section className="mx-auto max-w-5xl px-6 pb-20 motion-reveal">
        <CtaBand
          title="Order a loaf for collection"
          description="Pick a time. We will hold it at the counter."
          action={{ label: "Order a loaf", href: "/order" }}
        />
      </section>
    </SiteChrome>
  );
}

import { createFileRoute } from "@tanstack/react-router";
import { useState } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import { toast } from "sonner";

import { useCreateRow, useRows, type Row } from "@/lib/rows";
import { Button } from "@/components/ui/button";
import { Empty } from "@/components/ui/empty";
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import { FormRow } from "@/components/ui/form-row";
import { Input } from "@/components/ui/input";
import { PhoneInput } from "@/components/ui/phone-input";
import { RadioCards } from "@/components/ui/radio-cards";
import { SectionHeader } from "@/components/ui/section-header";
import { SiteChrome } from "@/components/ui/site-chrome";
import { Skeleton } from "@/components/ui/skeleton";
import { Spinner } from "@/components/ui/spinner";
import { SuccessPanel } from "@/components/ui/success-panel";
import { TimeSlot } from "@/components/ui/time-slot";

export const Route = createFileRoute("/order")({
  head: () => ({
    meta: [
      { title: "Order a loaf — Harbour Loaf" },
      { property: "og:title", content: "Order a loaf — Harbour Loaf" },
      {
        name: "description",
        content: "Choose a loaf from today's bake and a collection time at the counter.",
      },
      {
        property: "og:description",
        content: "Choose a loaf from today's bake and a collection time at the counter.",
      },
    ],
  }),
  component: Order,
});

type Loaf = Row & {
  name: string;
  description: string | null;
  price: number;
  photo: string | null;
};

type OrderRow = Row;

const CHROME = { secondAction: { label: "Call us", href: "tel:0117 496 0000" }, social: [{ network: "instagram", href: "https://instagram.com/harbourloaf" }],
  name: "Harbour Loaf",
  tagline: "A neighbourhood sourdough bakery in Bristol.",
  links: [{ label: "Today's bake", href: "/" }, { label: "The starter", href: "/starter" }, { label: "Visit", href: "/visit" }, { label: "Order", href: "/order" }],
  action: { label: "Order a loaf", href: "/order" },
  contact: {
    address: "Bristol",
    hours: "Wed–Sat 8–2, Sun 9–1",
  },
};

const SLOTS = [
  "08:00",
  "08:30",
  "09:00",
  "09:30",
  "10:00",
  "10:30",
  "11:00",
  "11:30",
  "12:00",
  "12:30",
  "13:00",
];

const orderSchema = z.object({
  customer_name: z.string().min(2, "Tell us your name"),
  phone: z.string().min(6, "We need a number for the counter"),
  loaf: z.string().min(1, "Pick a loaf"),
  pickup_date: z.string().min(1, "Pick a collection day"),
  pickup_time: z.string().min(1, "Pick a collection time"),
});

type OrderValues = z.infer<typeof orderSchema>;

function Order() {
  const loaves = useRows<Loaf>("loaves", { order: "price", dir: "asc" });
  const create = useCreateRow<OrderRow>("orders");
  const [sent, setSent] = useState(false);

  const form = useForm<OrderValues>({
    resolver: zodResolver(orderSchema),
    defaultValues: {
      customer_name: "",
      phone: "",
      loaf: "",
      pickup_date: "",
      pickup_time: "",
    },
  });

  const onSubmit = (values: OrderValues) => {
    create.mutate(
      {
        customer_name: values.customer_name,
        phone: values.phone,
        loaf: Number(values.loaf),
        pickup_date: values.pickup_date,
        pickup_time: values.pickup_time,
      },
      {
        onSuccess: () => {
          toast.success("Order received — see you at the counter.");
          form.reset();
          setSent(true);
        },
        onError: (e: Error) => toast.error(e.message),
      },
    );
  };

  if (sent) {
    return (
      <SiteChrome {...CHROME}>
        <div className="mx-auto max-w-lg px-6 py-20 motion-enter">
          <h1 className="sr-only">Order received</h1>
          <SuccessPanel
            title="Order received"
            description="See you at the counter. We'll have your loaf ready for the slot you picked. Pay when you collect."
            action={{ label: "Back to today's bake", href: "/" }}
          />
        </div>
      </SiteChrome>
    );
  }

  return (
    <SiteChrome {...CHROME}>
      <div className="mx-auto max-w-2xl px-6 py-14">
        <h1 className="text-3xl font-semibold tracking-tight">Order a loaf</h1>
        <SectionHeader
          className="mt-8"
          eyebrow="Collection"
          title="Pick a loaf and a collection slot"
          description="Your name, a phone number, and a time. Pay at the counter when you come."
        />

        <Form {...form}>
          <form onSubmit={form.handleSubmit(onSubmit)} className="mt-10 grid gap-6">
            <FormField
              control={form.control}
              name="loaf"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Today's loaves</FormLabel>
                  <FormControl>
                    <div>
                      {loaves.isPending && <Skeleton className="h-40 rounded-xl" />}
                      {loaves.isError && (
                        <p className="text-sm text-destructive">
                          Couldn't load today's bake. Refresh and try again.
                        </p>
                      )}
                      {loaves.data?.length === 0 && (
                        <Empty>
                          <p className="font-medium">Today's bake is not up yet</p>
                          <p className="text-sm text-muted-foreground">
                            Come back once the boards are written, or walk in and see what is left.
                          </p>
                        </Empty>
                      )}
                      {!!loaves.data?.length && (
                        <RadioCards
                          columns={1}
                          options={loaves.data.map((l) => ({
                            value: String(l.id),
                            label: l.name,
                            description: l.description
                              ? `£${l.price.toFixed(2)} · ${l.description}`
                              : `£${l.price.toFixed(2)}`,
                          }))}
                          value={field.value}
                          onChange={field.onChange}
                        />
                      )}
                    </div>
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name="customer_name"
              render={({ field, fieldState }) => (
                <FormRow
                  label="Your name"
                  htmlFor="customer_name"
                  required
                  error={fieldState.error?.message}
                >
                  <Input id="customer_name" autoComplete="name" {...field} />
                </FormRow>
              )}
            />

            <FormField
              control={form.control}
              name="phone"
              render={({ field, fieldState }) => (
                <FormRow
                  label="Phone"
                  htmlFor="phone"
                  required
                  hint="So we can reach you if a loaf runs short."
                  error={fieldState.error?.message}
                >
                  <PhoneInput id="phone" value={field.value} onChange={field.onChange} />
                </FormRow>
              )}
            />

            <FormField
              control={form.control}
              name="pickup_date"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Collection day</FormLabel>
                  <FormControl>
                    <Input type="date" min={new Date().toISOString().slice(0, 10)} {...field} />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name="pickup_time"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Collection time</FormLabel>
                  <FormControl>
                    <div className="flex flex-wrap gap-2 motion-stagger">
                      {SLOTS.map((t) => (
                        <TimeSlot
                          key={t}
                          time={t}
                          selected={field.value === t}
                          onSelect={() => field.onChange(t)}
                        />
                      ))}
                    </div>
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <p className="text-sm text-muted-foreground">
              Collection only — we do not deliver. Pay at the counter when you pick it up.
            </p>

            <div>
              <Button
                type="submit"
                className="motion-press"
                disabled={create.isPending || !loaves.data?.length}
              >
                {create.isPending ? <Spinner /> : null}
                {create.isPending ? "Sending…" : "Order a loaf"}
              </Button>
            </div>
          </form>
        </Form>
      </div>
    </SiteChrome>
  );
}

import { createFileRoute, Link } from "@tanstack/react-router";

export const Route = createFileRoute("/starter")({
  component: Unfinished,
  validateSearch: (search: Record<string, unknown>) => search,
});

function Unfinished() {
  return (
    <main className="mx-auto flex min-h-[70vh] max-w-xl flex-col items-center justify-center gap-4 px-6 text-center">
      <p className="text-xs font-medium uppercase tracking-[0.18em] text-muted-foreground">
        Still being written
      </p>
      <h1 className="text-3xl font-semibold tracking-tight text-balance">
        This page isn't finished yet
      </h1>
      <p className="text-muted-foreground">
        The rest of the site is live. Ask for this page again and it'll be written properly.
      </p>
      <Link
        to="/"
        className="mt-2 rounded-md border border-border px-5 py-2.5 text-sm font-medium"
      >
        Back to the home page
      </Link>
    </main>
  );
}

import { createFileRoute } from "@tanstack/react-router";

import { SITE_QRS } from "@/site-brand";
import { CtaBand } from "@/components/ui/cta-band";
import { Figure } from "@/components/ui/figure";
import { LocationCard } from "@/components/ui/location-card";
import { OpenNow } from "@/components/ui/open-now";
import { OpeningHours, type DayHours } from "@/components/ui/opening-hours";
import { SafeImage } from "@/components/ui/safe-image";
import { SectionHeader } from "@/components/ui/section-header";
import { SiteChrome } from "@/components/ui/site-chrome";

export const Route = createFileRoute("/visit")({
  head: () => ({
    meta: [
      { title: "Visit — Harbour Loaf" },
      { property: "og:title", content: "Visit — Harbour Loaf" },
      {
        name: "description",
        content: "Opening hours and how to find the bakery in Bristol.",
      },
      {
        property: "og:description",
        content: "Opening hours and how to find the bakery in Bristol.",
      },
    ],
  }),
  component: Visit,
});

const CHROME = { secondAction: { label: "Call us", href: "tel:0117 496 0000" }, social: [{ network: "instagram", href: "https://instagram.com/harbourloaf" }],
  name: "Harbour Loaf",
  tagline: "A neighbourhood sourdough bakery in Bristol.",
  links: [{ label: "Today's bake", href: "/" }, { label: "The starter", href: "/starter" }, { label: "Visit", href: "/visit" }, { label: "Order", href: "/order" }],
  action: { label: "Order a loaf", href: "/order" },
  contact: {
    address: "Bristol",
    hours: "Wed–Sat 8–2, Sun 9–1",
  },
};

const HOURS: DayHours[] = [
  { day: 1, label: "Monday", open: null, close: null },
  { day: 2, label: "Tuesday", open: null, close: null },
  { day: 3, label: "Wednesday", open: "08:00", close: "14:00" },
  { day: 4, label: "Thursday", open: "08:00", close: "14:00" },
  { day: 5, label: "Friday", open: "08:00", close: "14:00" },
  { day: 6, label: "Saturday", open: "08:00", close: "14:00" },
  { day: 0, label: "Sunday", open: "09:00", close: "13:00" },
];

function Visit() {
  return (
    <SiteChrome {...CHROME}>
      <section className="mx-auto max-w-5xl px-6 py-14">
        <h1 className="text-3xl font-semibold tracking-tight">Come and see us</h1>
        <SectionHeader
          className="mt-8"
          eyebrow="Visit"
          title="The shutters and the street"
          description="Walk in for whatever is left on the board, or order a collection and we will hold a loaf."
        />

        <div className="mt-10 grid gap-10 sm:grid-cols-2">
          <div>
            <OpenNow
              hours={HOURS.filter((h) => h.open && h.close).map((h) => ({
                day: h.day,
                open: h.open!,
                close: h.close!,
              }))}
            />
            <div className="mt-4 flex flex-wrap items-start gap-6">
              <OpeningHours days={HOURS} />
              {SITE_QRS.gallery ? (
                <Figure caption={SITE_QRS.gallery.label}>
                  <img
                    src={SITE_QRS.gallery.src}
                    alt={SITE_QRS.gallery.label}
                    className="size-[160px]"
                  />
                </Figure>
              ) : null}
            </div>
            <p className="mt-3 text-sm text-muted-foreground">We're closed on bank holidays.</p>
          </div>
          <div>
            <SafeImage
              src="/u/fold-lane-bakery/d5d591527a2bed3836f73b5e74e75565.jpg"
              alt="The counter and morning board at Harbour Loaf"
              ratio="4/3"
              fallbackSeed="counter"
            />
            <SafeImage
              className="mt-4"
              src="/u/fold-lane-bakery/8e6bd4818b036cfcd639d1bb5ec6156c.jpg"
              alt="A sourdough boule cooling after the morning bake"
              ratio="4/3"
              fallbackSeed="cooling-boule"
            />
            <LocationCard
              className="mt-4"
              name="Harbour Loaf"
              address="Bristol"
              note="On a side street a few minutes from the water. Look for the flour-dusted window and the morning board."
            />
          </div>
        </div>
      </section>

      <section className="mx-auto max-w-5xl px-6 pb-20 motion-reveal">
        <CtaBand
          title="Order a collection so we hold a loaf"
          description="Walk-ins are welcome for whatever is left. A collection order keeps your name on a loaf."
          action={{ label: "Order a loaf", href: "/order" }}
        />
      </section>
    </SiteChrome>
  );
}

import { createFileRoute } from "@tanstack/react-router";

