import { createFileRoute } from "@tanstack/react-router";

import { CtaBand } from "@/components/ui/cta-band";
import { KeyPoints } from "@/components/ui/key-points";
import { SafeImage } from "@/components/ui/safe-image";
import { SectionHeader } from "@/components/ui/section-header";
import { SiteChrome } from "@/components/ui/site-chrome";
import { Steps } from "@/components/ui/steps";
import { StoryLead } from "@/components/ui/story-lead";

export const Route = createFileRoute("/classes")({
  head: () => ({
    meta: [
      { title: "Bread Classes — Harbour Loaf" },
      { property: "og:title", content: "Bread Classes — Harbour Loaf" },
      {
        name: "description",
        content: "Saturday bread-making classes at Harbour Loaf in Bristol.",
      },
      {
        property: "og:description",
        content: "Saturday bread-making classes at Harbour Loaf in Bristol.",
      },
    ],
  }),
  component: BreadClasses,
});

const CHROME = { secondAction: { label: "Call us", href: "tel:0117 496 0000" }, social: [{ network: "instagram", href: "https://instagram.com/harbourloaf" }],
  name: "Harbour Loaf",
  tagline: "A neighbourhood sourdough bakery in Bristol.",
  links: [{ label: "Today's bake", href: "/" }, { label: "The starter", href: "/starter" }, { label: "Visit", href: "/visit" }, { label: "Gallery", href: "/gallery" }, { label: "Classes", href: "/classes" }, { label: "Order", href: "/order" }],
  action: { label: "Order a loaf", href: "/order" },
  contact: {
    address: "Bristol",
    hours: "Wed–Sat 8–2, Sun 9–1",
  },
};

function BreadClasses() {
  return (
    <SiteChrome {...CHROME}>
      <section className="mx-auto max-w-5xl px-6 py-14">
        <h1 className="text-3xl font-semibold tracking-tight">Bread Classes</h1>
        <SectionHeader
          className="mt-8"
          eyebrow="Saturdays"
          title="Bread-making at the bakery"
          description="A Saturday morning at Harbour Loaf: mix, fold, shape and bake with the same dough that goes on the counter, then take a loaf home."
        />

        <div className="mt-10 max-w-3xl">
          <StoryLead
            kicker="At Harbour Loaf"
            headline="Spend a Saturday morning with the starter"
            standfirst="Once a week we set a few extra places at the bench and walk a small group through the bake. You work by hand, at the pace of the dough, and leave with a loaf you made."
          />
        </div>

        <SafeImage
          className="mt-10"
          src="/u/fold-lane-bakery/8e6bd4818b036cfcd639d1bb5ec6156c.jpg"
          alt="A sourdough boule cooling after the morning bake"
          ratio="16/9"
          fallbackSeed="class-bake"
        />

        <SectionHeader
          className="mt-16"
          eyebrow="The morning"
          title="How a Saturday class runs"
          description="From the first mix to a loaf you carry home."
        />
        <div className="mt-8">
          <Steps
            columns={1}
            items={[
              {
                title: "Arrive and meet the starter",
                description:
                  "Saturday morning, before the counter gets busy. Coffee, an apron, and a look at the crock that has been fed since we opened.",
              },
              {
                title: "Mix the dough",
                description:
                  "Stoneground flour, water, salt, and the starter. You mix by hand and learn the feel of a dough that will take a long prove.",
              },
              {
                title: "Fold, shape and score",
                description:
                  "A few folds as it strengthens, then shape into a boule or batard, rest, and score before it goes in.",
              },
              {
                title: "Bake and take it home",
                description:
                  "Your loaf comes out with the morning bake. Cool it a little at the rack, then carry it home still warm.",
              },
            ]}
          />
        </div>

        <div className="mt-16">
          <KeyPoints
            title="In short"
            points={[
              "Saturday mornings only — the class runs while the bakery is open.",
              "Small groups, so everyone has space at the bench.",
              "You take home the loaf you mixed, shaped and baked.",
              "No experience needed. We work at the pace of the dough.",
            ]}
          />
        </div>
      </section>

      <section className="mx-auto max-w-5xl px-6 pb-20 motion-reveal">
        <CtaBand
          title="Come in and ask at the counter"
          description="Places are few. Call in on a weekday, or ask when you collect a loaf, and we will tell you the next Saturday that has space."
          action={{ label: "How to find us", href: "/visit" }}
        />
      </section>
    </SiteChrome>
  );
}
